#!/usr/bin/env Rscript

# -----------------------------------------------------------------------------
# Figure 6C plotting script
#
# Purpose:
# Distribution of patient-level median relative abundance of Bacteroidota
# families (plus Akkermansiaceae) after quinolone prophylaxis.
#
# Input:
# - data/figure6/family_abundance.csv (generated by 00_generate_family_abundance.R)
#
# Outputs:
# - results/figure6/Fig6C.pdf
# - results/figure6/Fig6C_patient_medians.csv
# -----------------------------------------------------------------------------

suppressPackageStartupMessages({
  library(tidyverse)
})

dir.create("results/figure6", showWarnings = FALSE, recursive = TRUE)

if (!file.exists("data/figure6/family_abundance.csv")) {
  source("figure6_scripts/00_generate_family_abundance.R")
}

custom_theme <- theme(
  panel.grid = element_blank(),
  panel.background = element_blank(),
  panel.border = element_rect(color = "black", fill = NA, linewidth = 0.75),
  axis.text = element_text(color = "black", size = 10)
)

# -----------------------------------------------------------------------------
# 1) Post-prophylaxis samples and patient medians
# -----------------------------------------------------------------------------

message("Loading family abundance table...")
family_abundance <- read_csv("data/figure6/family_abundance.csv", show_col_types = FALSE,
                             col_types = cols(SampleID = col_character(), PatientID = col_character()))

# Post-prophylaxis samples: at least one day after the first quinolone day.
# Patients without quinolones in [-10, 0] contribute no post samples.
post_samples <- family_abundance %>%
  filter(!is.na(first_quin_day), DayRelativeToNearestHCT >= first_quin_day + 1)

patient_medians <- post_samples %>%
  select(PatientID, ends_with("_abund")) %>%
  pivot_longer(cols = ends_with("_abund"), names_to = "family", values_to = "abundance") %>%
  mutate(family = str_remove(family, "_abund$")) %>%
  group_by(PatientID, family) %>%
  summarise(median_abundance = median(abundance, na.rm = TRUE), .groups = "drop")

# Families ordered by the median (then 75th percentile, then mean) of patient medians.
family_order <- patient_medians %>%
  group_by(family) %>%
  summarise(
    med = median(median_abundance, na.rm = TRUE),
    p75 = quantile(median_abundance, 0.75, na.rm = TRUE),
    mean_val = mean(median_abundance, na.rm = TRUE),
    .groups = "drop"
  ) %>%
  arrange(desc(med), desc(p75), desc(mean_val)) %>%
  pull(family)

message(sprintf("Patients: %d | post-prophylaxis samples: %d",
                n_distinct(patient_medians$PatientID), nrow(post_samples)))

# -----------------------------------------------------------------------------
# 2) Plot
# -----------------------------------------------------------------------------

message("Generating Fig6C...")
fig6c <- ggplot(patient_medians,
                aes(x = factor(family, levels = family_order),
                    y = log10(median_abundance + 1e-5))) +
  geom_boxplot(outlier.shape = NA, alpha = 0.7, fill = "gray75") +
  geom_jitter(width = 0.2, alpha = 0.2, color = "gray20") +
  labs(x = "Family", y = "log10(median relative abundance per patient)") +
  custom_theme +
  theme(legend.position = "none", axis.text.x = element_text(angle = 45, hjust = 1))

ggsave("results/figure6/Fig6C.pdf", fig6c, width = 5, height = 5)
write_csv(patient_medians, "results/figure6/Fig6C_patient_medians.csv")

message("Saved: results/figure6/Fig6C.pdf")
message("Saved: results/figure6/Fig6C_patient_medians.csv")
